// Rescue feature — data contract. STABLE SCHEMA: the MILES replica screens (src/miles/) read the same file.
//
// GET https://miles.bolls.dev/app/api/vehicles.json   (bundled copy: src/data/vehicles.json, used offline / on error)
// Generated by scripts/build_rescue_data.py from miles-ops/backend/geo/replay_berlin_2024-06.parquet.
// DEMO DATA: one snapshot (Tue 18 Jun 2024, 21:00 Berlin) of the June 2024 replay. Positions, models, masked plates and
// fuel levels are real replay rows; nothing is live. Every surface showing it must say "demo data".
//
// {
//   "meta": {
//     "source": "June 2024 Berlin replay (MILES open fleet data)",
//     "snapshot": "Tue 18 Jun 2024, 21:00",          // human label
//     "snapshotIso": "2024-06-18T21:00:00+02:00",
//     "model": "TabPFN P(idle > 12 h), precomputed out-of-sample",
//     "rescueRule": "p_tabpfn >= 0.4556 (top 10% of replay ride ends) and parked < 12 h",
//     "valueMap": "observed median idle per 1 km cell, weekday 19-23 h ride ends, June 3-22 2024",
//     "demo": true,
//     "center": { "lat", "lon", "name" }               // CIC Berlin
//   },
//   "demoPosition": { "lat", "lon", "name" },          // default "you" for the demo (Elsenstraße, Treptow)
//   "vehicles": [ Vehicle, ... ]                       // every car parked at the snapshot within 4.5 km of CIC (~900)
// }
//
// Vehicle (all fields always present unless marked optional):
//   id: number          MILES vehicle id from the replay
//   lat, lon: number
//   model: string       e.g. "VW Polo GP 2022", "Mercedes Sprinter"
//   plate: string       masked as in the source, e.g. "B-MI ••10"
//   size: string        MILES size class: S | M | P (premium) | L | X (vans are L/X)
//   ev: boolean
//   pct: number         fuel / charge level 0..100
//   kmPrice: number     € per km (assumed standard rate, see miles-drive/app.py)
//   unlock: number      € unlock fee
//   parkedH: number     hours parked at the snapshot
//   rescue?: RescueInfo present ONLY for rescue candidates (~160): show the €5 badge on these
//
// RescueInfo:
//   p: number           TabPFN P(idle > 12 h after the ride end), out-of-sample (June 17-22 rows, June 3-16 context)
//   area: string        nearest named place to where it stands
//   waitHereH: number|null  observed median idle (h) of its 1 km cell, weekday evenings (null if < 15 events)
//   dest: { name, lat, lon, waitH, m } | null
//                       value-map destination: the 1 km cell 0.6-2.5 km away with the lowest observed median idle
//                       (waitH, hours) for the same vehicle type (cars vs vans); m = straight-line metres from the car

export type RescueDest = { name: string; lat: number; lon: number; waitH: number; m: number };

export type RescueInfo = {
  p: number;
  area: string;
  waitHereH: number | null;
  dest: RescueDest | null;
};

export type Vehicle = {
  id: number;
  lat: number;
  lon: number;
  model: string;
  plate: string;
  size: string;
  ev: boolean;
  pct: number;
  kmPrice: number;
  unlock: number;
  parkedH: number;
  rescue?: RescueInfo;
};

export type FleetMeta = {
  source: string;
  snapshot: string;
  snapshotIso?: string;
  model: string;
  rescueRule: string;
  valueMap: string;
  demo: boolean;
  center: { lat: number; lon: number; name: string };
};

export type FleetDoc = {
  meta: FleetMeta;
  vehicles: Vehicle[];
  demoPosition: { lat: number; lon: number; name: string };
};

export type LatLon = { lat: number; lon: number };

/** An offer as shown to a user standing at a given point. */
export type ScoredRescue = Vehicle & {
  rescue: RescueInfo;
  credit: number;
  walkM: number;
  walkMin: number;
  stillThere: number;
  score: number;
};

export type RescueStage = "idle" | "walking" | "driving" | "done";
